SELECT count() AS matched, countIf(tuple(t.author_key, t.created_at, t.link_created_at, t.updated_at, t.deleted, t.collection_name, t.tags, t.ref_value, t.comment_post_id, t.repost_of) <> tuple(d.author_key, d.created_at, g.created_at, g.updated_at, g.deleted, d.collection_name, d.tags, d.ref_value, JSONExtractString(d.body, 'post_id'), JSONExtractString(d.body, 'repost_of'))) AS mismatched FROM (SELECT * FROM doc_groups_t WHERE cityHash64(doc_id) % 2 = 0) AS t INNER JOIN (SELECT * FROM (SELECT * FROM doc_groups FINAL WHERE cityHash64(doc_id) % 2 = 0) AS doc_groups WHERE deleted = 0) AS g ON t.doc_id = g.doc_id AND t.group_id = g.group_id INNER JOIN (SELECT * FROM (SELECT * FROM documents FINAL WHERE cityHash64(doc_id) % 2 = 0) AS documents WHERE deleted = 0) AS d ON t.doc_id = d.doc_id AND t.author_key = d.author_key
